#include <stdio.h>
#include <string.h>
#include <limits.h>

char mostFreqChar(const char *s) {
    if (s == NULL || s[0] == '\0') {
        return '\0';
    }

    int freq[256] = {0};
    int maxFreq = 0;
    char result = '\0';

    for (int i = 0; s[i] != '\0'; i++) {
        unsigned char c = (unsigned char)s[i];
        freq[c]++;

        if (freq[c] > maxFreq) {
            maxFreq = freq[c];
            result = c;
        }
    }

    return result;
}

int main() {
    // Test case 1: Normal case with unique maximum
    const char *test1 = "hello world";
    char result1 = mostFreqChar(test1);
    printf("Test 1: '%s' -> '%c'\n", test1, result1);

    // Test case 2: Tie - should return first occurring
    const char *test2 = "aabb";
    char result2 = mostFreqChar(test2);
    printf("Test 2: '%s' -> '%c'\n", test2, result2);

    // Test case 3: Empty string
    const char *test3 = "";
    char result3 = mostFreqChar(test3);
    printf("Test 3: '%s' -> '%c'\n", test3, result3 ? result3 : ' ');

    // Test case 4: Single character
    const char *test4 = "zzzz";
    char result4 = mostFreqChar(test4);
    printf("Test 4: '%s' -> '%c'\n", test4, result4);

    // Test case 5: Mixed case with numbers
    const char *test5 = "test123test";
    char result5 = mostFreqChar(test5);
    printf("Test 5: '%s' -> '%c'\n", test5, result5);

    return 0;
}

