import java.util.*;

public class Solution {
    public static String mostFreqChar(String s) {
        if (s.isEmpty()) {
            return "";
        }
        int n = s.length();
        int[] counts = new int[256];
        int[] firstPos = new int[256];
        Arrays.fill(firstPos, -1);
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            int idx = c;
            counts[idx]++;
            if (firstPos[idx] == -1) {
                firstPos[idx] = i;
            }
        }
        int maxCount = 0;
        int bestChar = 0;
        for (int i = 0; i < 256; i++) {
            if (counts[i] > maxCount) {
                maxCount = counts[i];
                bestChar = i;
            } else if (counts[i] == maxCount && maxCount > 0) {
                if (firstPos[i] < firstPos[bestChar]) {
                    bestChar = i;
                }
            }
        }
        return String.valueOf((char) bestChar);
    }

    public static void main(String[] args) {
        System.out.println(mostFreqChar(""));                     // empty
        System.out.println(mostFreqChar("a"));                    // single char
        System.out.println(mostFreqChar("abacabad"));             // 'a' appears 4 times
        System.out.println(mostFreqChar("hello world"));          // 'l' appears 3 times
        System.out.println(mostFreqChar("tie test"));             // 't' and 'e' tie, 't' first
        System.out.println(mostFreqChar("aaabbb"));               // 'a' and 'b' tie, 'a' first
        System.out.println(mostFreqChar("AaaBBb"));               // case sensitive
    }
}
